      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "Khai Dinh's tomb is a wild mix of European pomp and Vietnamese dragons, all in grey concrete."
    },
    {
      "poi_id": "p10",
      "kind": "meal",
      "must_do_id": null,
      "note": "Madam Thu does a proper spread of local dishes, a good pause between emperors."
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tu Duc's tomb feels like a poet's garden, all pine hills and lotus ponds hiding a modest emperor's rest."
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "Minh Mang's tomb is the grandest of the lot, a perfect balance of courtyards, lakes and forest."
    }
  ]
}
